<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\CommissionSettlementService;

Auth::requirePermission('promoters.manage');$tenantId=em_require_tenant();
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    try{
        if($action==='save'){
            $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$code=strtoupper(trim((string)($_POST['code']??'')));$pct=(float)str_replace(',','.',(string)($_POST['commission_percent']??'0'));$userId=(int)($_POST['user_id']??0);if($name===''||$code===''||$pct<0||$pct>100)throw new RuntimeException('Promotor inválido.');if($userId){$u=$pdo->prepare('SELECT id FROM users WHERE id=? AND tenant_id=? AND role="promoter"');$u->execute([$userId,$tenantId]);if(!$u->fetchColumn())throw new RuntimeException('Usuário promotor inválido.');}
            if($id){$s=$pdo->prepare('UPDATE promoters SET user_id=?,name=?,code=?,commission_percent=?,active=? WHERE id=? AND tenant_id=?');$s->execute([$userId?:null,$name,$code,$pct,isset($_POST['active'])?1:0,$id,$tenantId]);}
            else{$s=$pdo->prepare('INSERT INTO promoters (tenant_id,user_id,name,code,commission_percent,active) VALUES (?,?,?,?,?,1)');$s->execute([$tenantId,$userId?:null,$name,$code,$pct]);$id=(int)$pdo->lastInsertId();}
            Auth::audit('promoter.saved','promoter',(string)$id);em_flash('ok','Promotor salvo.');em_go('promoters');
        }
        if($action==='commission-paid'){
            (new CommissionSettlementService())->settle((int)($_POST['id']??0),(int)($_POST['account_id']??0));em_flash('ok','Comissão paga e registrada no Financeiro.');em_go('promoters');
        }
        throw new RuntimeException('Ação inválida.');
    }catch(Throwable$e){em_flash('error',$e->getMessage());em_go('promoters');}
}
$users=$pdo->prepare('SELECT id,name,email FROM users WHERE tenant_id=? AND role="promoter" AND status="active" ORDER BY name');$users->execute([$tenantId]);$users=$users->fetchAll();
$s=$pdo->prepare('SELECT p.*,u.email,(SELECT COALESCE(SUM(pc.amount_cents),0) FROM promoter_commissions pc WHERE pc.promoter_id=p.id AND pc.status IN ("approved","paid")) earned,(SELECT COALESCE(SUM(pc.amount_cents),0) FROM promoter_commissions pc WHERE pc.promoter_id=p.id AND pc.status="approved") payable,(SELECT COUNT(*) FROM orders o WHERE o.promoter_id=p.id AND o.payment_status="paid") sales FROM promoters p LEFT JOIN users u ON u.id=p.user_id WHERE p.tenant_id=? ORDER BY p.name');$s->execute([$tenantId]);$promoters=$s->fetchAll();
$c=$pdo->prepare('SELECT pc.*,p.name promoter_name,o.total_cents order_total FROM promoter_commissions pc JOIN promoters p ON p.id=pc.promoter_id JOIN orders o ON o.id=pc.order_id WHERE pc.tenant_id=? ORDER BY pc.id DESC LIMIT 100');$c->execute([$tenantId]);$commissions=$c->fetchAll();
$accounts=[];if(Auth::can('finance.manage')){$a=$pdo->prepare('SELECT id,name,account_type FROM financial_accounts WHERE tenant_id=? AND active=1 ORDER BY name');$a->execute([$tenantId]);$accounts=$a->fetchAll();}
em_header('Promotores e afiliados','promoters');
?><section class="page-hero"><div><span class="eyebrow">AFILIADOS E COMISSÕES</span><h2>Promotores</h2><p>Comissões aprovadas permanecem como obrigação financeira até a liquidação em uma conta bancária, carteira ou caixa.</p></div><?php if(Auth::can('finance.view')):?><div class="hero-actions"><a class="button secondary" href="<?= Security::e(app_url('?route=finance')) ?>">Financeiro</a></div><?php endif;?></section><div class="grid" style="grid-template-columns:minmax(280px,1fr) minmax(0,2fr)"><section class="card"><h2>Novo promotor</h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="save"><label class="span-2">Nome<input name="name" required></label><label>Código<input name="code" required placeholder="JULIO10"></label><label>Comissão %<input name="commission_percent" inputmode="decimal" value="5"></label><label class="span-2">Usuário vinculado<select name="user_id"><option value="0">Sem login</option><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>"><?= Security::e($u['name'].' · '.$u['email']) ?></option><?php endforeach;?></select></label><button class="primary span-2">Criar promotor</button></form></section><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Promotor</th><th>Código</th><th>Comissão</th><th>Vendas</th><th>Gerado</th><th>A pagar</th></tr></thead><tbody><?php foreach($promoters as $p):?><tr><td><strong><?= Security::e($p['name']) ?></strong><br><span class="muted"><?= Security::e($p['email']??'') ?></span></td><td><code><?= Security::e($p['code']) ?></code></td><td><?= Security::e((string)$p['commission_percent']) ?>%</td><td><?= (int)$p['sales'] ?></td><td><?= em_money($p['earned']) ?></td><td><strong><?= em_money($p['payable']) ?></strong></td></tr><?php endforeach;?></tbody></table></div></section></div><section class="card" style="margin-top:18px"><div class="section-head"><div><h2>Comissões recentes</h2><p class="muted">Ao pagar, escolha de qual conta o dinheiro saiu.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Promotor</th><th>Pedido</th><th>Venda</th><th>Comissão</th><th>Status</th><th>Liquidação</th></tr></thead><tbody><?php foreach($commissions as $c):?><tr><td><?= Security::e($c['promoter_name']) ?></td><td>#<?= (int)$c['order_id'] ?></td><td><?= em_money($c['order_total']) ?></td><td><strong><?= em_money($c['amount_cents']) ?></strong></td><td><span class="badge"><?= $c['status']==='paid'?'Paga':'A pagar' ?></span></td><td><?php if($c['status']==='approved'&&Auth::can('finance.manage')):?><?php if($accounts):?><form method="post" style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="commission-paid"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><select name="account_id" required><option value="">Conta de saída</option><?php foreach($accounts as$a):?><option value="<?= (int)$a['id'] ?>"><?= Security::e($a['name']) ?></option><?php endforeach;?></select><button class="secondary compact">Pagar</button></form><?php else:?><a class="button secondary compact" href="<?= Security::e(app_url('?route=finance')) ?>">Cadastrar conta</a><?php endif;?><?php elseif($c['status']==='paid'):?><span class="muted">Liquidada</span><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php em_footer();